  "video/mp4;codecs=h264",
  // H.264: Fast and widely supported in MP4
  "video/mp4;codecs=h264,aac",
  // H.264 with AAC in MP4
  "video/webm;codecs=vp8",
  // VP8: Fast encoding, WebRTC standard (WebM only)
  "video/mp4",
  // MP4 container auto-select
  // Medium speed codecs - balance of speed and quality
  "video/webm;codecs=vp9",
  // VP9: Better compression but slower (WebM only)
